mapper.select:
SELECT 
  FROM public."GAM_対戦情報" m
  LEFT JOIN public."ACC_アカウント" p
    ON p."アカウントID" = CASE WHEN m."挑戦者アカウントID" = #{viewerAccountId}
                              THEN m."相手アカウントID" ELSE m."挑戦者アカウントID" END
 WHERE m."対戦ID" = #{matchId}

mapper.update:
UPDATE public."GAM_対戦情報"
   SET "状態コード" = 'DECLINED',
       "バージョン" = "バージョン" + 1,
       "更新者アカウントID" = #{opponentAccountId},
       "更新日時" = CURRENT_TIMESTAMP
 WHERE "対戦ID" = #{matchId}
   AND "相手アカウントID" = #{opponentAccountId}
   AND "状態コード" = 'WAITING'
   AND "バージョン" = #{version}

UPDATE public."GAM_対戦情報"
   SET "状態コード" = 'CANCELLED',
       "バージョン" = "バージョン" + 1,
       "更新者アカウントID" = #{challengerAccountId},
       "更新日時" = CURRENT_TIMESTAMP
 WHERE "対戦ID" = #{matchId}
   AND "挑戦者アカウントID" = #{challengerAccountId}
   AND "状態コード" = 'WAITING'
   AND "バージョン" = #{version}
